const fs = require('fs');
const https = require('https');

// Read the .env.test file
const envContent = fs.readFileSync('.env.test', 'utf8');

// Parse environment variables (skip comments and empty lines)
const envVars = {};
const lines = envContent.split('\n');

for (const line of lines) {
  const trimmedLine = line.trim();
  // Skip empty lines and comments
  if (!trimmedLine || trimmedLine.startsWith('#')) {
    continue;
  }

  // Parse KEY=VALUE format
  const equalIndex = trimmedLine.indexOf('=');
  if (equalIndex > 0) {
    const key = trimmedLine.substring(0, equalIndex).trim();
    const value = trimmedLine.substring(equalIndex + 1).trim();
    envVars[key] = value;
  }
}

// Create JSON payload
const payload = JSON.stringify(envVars, null, 2);
console.log('Environment variables parsed:');
console.log(payload);

// Prepare the POST request
const options = {
  hostname: 'localhost',
  port: 3003,
  path: '/api/doc-export',
  method: 'POST',
  headers: {
    'Content-Type': 'application/json',
    'Content-Length': Buffer.byteLength(payload)
  }
};

const req = https.request(options, (res) => {
  console.log(`\nResponse Status: ${res.statusCode}`);
  console.log(`Response Headers: ${JSON.stringify(res.headers)}`);

  let responseData = '';
  res.on('data', (chunk) => {
    responseData += chunk;
  });

  res.on('end', () => {
    console.log(`Response Body: ${responseData}`);
  });
});

req.on('error', (error) => {
  console.error(`Error: ${error.message}`);
});

// Send the request
req.write(payload);
req.end();

